/*
  The JSX types of the mds-* tags, for the pages of the studio.

  They come from the Magma installed where the studio runs: the `JSX.IntrinsicElements` its build
  publishes (`dist/types/components.d.ts`, generated by Stencil from the props and the events of
  each component). The import is a type: nothing of Magma reaches the bundle (#695,
  test/bundle.test.mts), and a prop renamed or removed in Magma fails `check.types` here.

  Two changes for Preact:
  - the events: Magma names their handlers `onMdsInputChange`; the studio writes them
    `onmdsInputChange`, since Preact listens to the event named by what follows `on`, and a name
    that starts lowercase keeps the name of the event as it is (`mdsInputChange`, magma.tsx);
  - the attributes Preact takes on any element (`class`, `style`, `ref`, `aria-*`, the DOM events),
    less the ones Magma declares itself (`size`, `type`, `label`...), which keep the type of Magma.
*/
import type { JSX as Magma } from '@maggioli-design-system/magma';
import type { HTMLAttributes } from 'preact';

/** The props of a tag with the handlers of its events named as Preact listens to them. */
type PreactEvents<Props> = {
  [Name in keyof Props as Name extends `onMds${infer Rest}` ? `onmds${Rest}` : Name]: Props[Name];
};

type Tag = keyof Magma.IntrinsicElements;

type MagmaElement<T extends Tag> = PreactEvents<Magma.IntrinsicElements[T]> &
  Omit<HTMLAttributes<HTMLElementTagNameMap[T]>, keyof PreactEvents<Magma.IntrinsicElements[T]>>;

type MagmaElements = { [T in Tag]: MagmaElement<T> };

declare module 'preact' {
  namespace JSX {
    // eslint-disable-next-line @typescript-eslint/no-empty-object-type -- only an interface merges into the one of Preact
    interface IntrinsicElements extends MagmaElements {}
  }
}
